"""Author-specified high-contrast palette, dense review figures. Source measurements are immutable."""
import csv,json,hashlib,shutil,io
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.ticker import LogLocator,NullLocator
P=Path('embedded');B=P/'results/paper/final_resident864_20261016'
O=Path(__file__).resolve().parent.parent/'figs/current';O.mkdir(parents=True,exist_ok=True)
COL=['#0072BD','#D95319','#EDB120','#7E2F8E','#77AC30','#4DBEEE'];MK=['o','s','D','^','x','v']
SOURCES={};ASSETS=[];POINTS=[]

plt.rcParams.update({'font.family':'STIXGeneral','font.size':9,'axes.labelsize':9,'axes.titlesize':8.5,'legend.fontsize':8.5,'xtick.labelsize':8.5,'ytick.labelsize':8.5,'axes.linewidth':.65,'pdf.fonttype':42,'ps.fonttype':42,'savefig.dpi':300})

from ieee_style import apply as apply_ieee_style
apply_ieee_style()
def paired_times(ax, labels, pairs, colors, qualified=None):
 pairs=np.asarray(pairs,dtype=float);top=float(pairs.max())
 for j,col in enumerate(colors):
  xs=np.arange(len(labels))*1.45+(-.28 if j==0 else .28)
  vals=pairs[:,j]
  ax.bar(xs,vals,width=.52,color=col,zorder=3)
  for x,value in zip(xs,vals):
   # Anchor FastSET labels toward the left of their bars, clear of CNN.
   ax.annotate(f'{value:.2f}',(x,value+top*(.025 if j==0 else .065)),
               xytext=(-3 if j==0 else 0,0),textcoords='offset points',
               rotation=0,ha='center',va='bottom',
               fontsize=9,color='black',zorder=5)
 for i,(ff,cc) in enumerate(pairs):
  y=max(ff,cc)+top*.21;x=i*1.45
  ax.plot([x-.28,x-.28,x+.28,x+.28],[y-top*.02,y,y,y-top*.02],color='#555555',lw=.7,zorder=4)
  ax.text(x,y+top*.025,f'{cc/ff:.1f}×',ha='center',va='bottom',fontsize=9)
 ax.set(xticks=np.arange(len(labels))*1.45,xticklabels=labels,ylabel='Time (s)',ylim=(0,top*1.45),xlim=(-.85,(len(labels)-1)*1.45+.85))
 ax.grid(axis='y',color='#d6d6d6',lw=.5);ax.set_axisbelow(True);ax.tick_params(direction='in',pad=2)


def sha(p):
 return hashlib.sha256(p.read_bytes()).hexdigest()

def rows(p):
 return list(csv.DictReader(io.StringIO(DATA_CSV[Path(p).relative_to(P).as_posix()])))

def style(ax,xlabel=r'$E_b/N_0$ (dB)',snr=True,xmax=12,low=2e-8,high=.7):
 ax.set(yscale='log',xlabel=xlabel,ylabel='BER',ylim=(low,high))
 ax.yaxis.set_major_locator(LogLocator(base=10,numticks=6));ax.yaxis.set_minor_locator(NullLocator());ax.tick_params(direction='in',length=3,width=.65,labelleft=True)
 ax.grid(axis='both',which='major',color='#d6d6d6',lw=.5);ax.set_axisbelow(True)
 ax.axhline(2e-4,color='#777777',lw=.9,ls=(0,(3,3)),zorder=1)
 ax.text(.025,2.25e-4,'Target: 2e-4',transform=ax.get_yaxis_transform(),ha='left',va='bottom',color='#666666',fontsize=8.5,bbox=dict(fc='white',ec='none',pad=.2,alpha=.8))
 if snr:ax.set(xticks=list(range(4,xmax+1,2)),xlim=(3.85,xmax+.15))
def curve(ax,rr,x,label,col,marker,ls='-',asset='',panel=''):
 if label in ['CNN est.','LS','Perfect CSI']:ls={'CNN est.':'-.','LS':'--','Perfect CSI':':'}[label]
 rr=sorted(rr,key=lambda r:float(r[x]))
 if x=='snr':rr=[r for r in rr if float(r[x])<=int(np.floor(ax.get_xlim()[1]))]  # End at last displayed SNR; no segment towards an off-screen sample.
 assert rr,(asset,label)
 xx=[];yy=[]
 for r in rr:
  e=int(r['bit_errors']);n=int(r['bits']);ber=e/n;assert abs(ber-float(r['ber']))<max(1e-15,ber*1e-12)
  xx.append(float(r[x]));yy.append(ber if e else 1/n)
  POINTS.append(dict(asset=asset,panel=panel,series=label,x=xx[-1],bit_errors=e,bits=n,ber=ber,display_ber=yy[-1]))
 ax.plot(xx,yy,label=label,color=col,marker=marker,ms=4.5,mfc='white',mew=.8,markevery=sorted(set(range(0,len(rr),2 if x=='snr' else max(2,len(rr)//8)))|{len(rr)-1}),ls=ls,lw=1.85)
 zz=[(float(r[x]),1/int(r['bits'])) for r in rr if int(r['bit_errors'])==0]
 if zz:ax.scatter(*zip(*zz),marker='v',s=24,color=col,zorder=6)
def finish(fig,name,caption,wide=False):
 if 'fullrange' in name:caption=caption.replace('the main display is 4–12 dB','this supplemental display is 4–18 dB')
 # Fit y limits to the points visible in the selected x window, including zero-error display marks.
 for ax in fig.axes:
  if ax.get_yscale()!='log':continue
  lo,hi=ax.get_xlim();yy=[2e-4]
  for line in ax.lines:
   x=np.asarray(line.get_xdata(),dtype=float);y=np.asarray(line.get_ydata(),dtype=float)
   if len(x)>0 and not line.get_label().startswith('_'):yy.extend(y[(x>=lo)&(x<=hi)&(y>0)].tolist())
  def nice(v,up):
   power=10**np.floor(np.log10(v));z=v/power;options=[1,2,5,10]
   return (min(k for k in options if k>=z) if up else max(k for k in options if k<=z))*power
  ax.set_ylim(nice(min(yy)*.65,False),nice(max(yy)*1.3,True))
 for ax in fig.axes:
  h,l=ax.get_legend_handles_labels()
  if len(l)==6 and ax.get_legend() is not None:
   order=[0,2,4,1,3,5];ax.legend([h[i] for i in order],[l[i] for i in order],ncol=2,frameon=False,loc='lower center',bbox_to_anchor=(.5,1),columnspacing=.8,handlelength=2.4,fontsize=8.5)
 for ext in ['png','pdf','svg']:fig.savefig(O/(name+'.'+ext),bbox_inches='tight',pad_inches=.035)
 ASSETS.append(dict(name=name,pdf=name+'.pdf',png=name+'.png',caption=caption,wide=wide,placement='double-column' if wide else 'single-column',figure_inches=list(fig.get_size_inches()),axes=[dict(xlabel=ax.get_xlabel(),ylabel=ax.get_ylabel(),xlim=list(ax.get_xlim()),ylim=list(ax.get_ylim()),xticks=[float(v) for v in ax.get_xticks()]) for ax in fig.axes]))
 plt.close(fig)
ZERO='Gray dashed line: target BER 2e-4. Zero observed errors are shown as downward triangles at 1/N only for the logarithmic display, not as measured nonzero BER. Complete 4–18 dB data remain in source CSVs; the main display is 4–12 dB.'
TIME='Time adds historical measured update time and separately measured data input time under normal OS caching; BER evaluation and initialization/first compilation are excluded. It is a sum of measured components, not a new continuous end-to-end latency.'

