def main(only=None):
 mc=rows(B/'source_data/cnnest/five_method_metrics.csv')
 styles=list(zip(['FastSET8-64','CNN','CNNEst','LS','Perfect'],['FastSET','CNN','CNN est.','LS','Perfect CSI'],COL,MK))
 for cases,name,xmax in [(['A2B','A2C'],'main_ber',12),(['A2B'],'A2B_five_methods',12),(['A2C'],'A2C_five_methods',12),(['A2B','A2C'],'main_ber_fullrange',18)]:
  if only is not None and name not in only:continue
  stacked=len(cases)==2
  fig,axes=plt.subplots(len(cases),1,figsize=(3.5,4.5) if stacked else (3.5,2.35),squeeze=False)
  for ax,case in zip(axes.flat,cases):
   style(ax,xmax=xmax)
   for method,label,col,mk in styles:curve(ax,[r for r in mc if r['scenario']==case and r['method']==method],'snr',label,col,mk,asset=name,panel=case)
  h,l=axes[0,0].get_legend_handles_labels();fig.legend(h,l,ncol=3,loc='upper center',bbox_to_anchor=(.54,.998),frameon=False,handlelength=2.4,columnspacing=.65,labelspacing=.25,borderpad=0)
  if stacked:fig.subplots_adjust(left=.19,right=.99,bottom=.105,top=.88,hspace=.42)
  else:fig.subplots_adjust(left=.17,right=.99,bottom=.20,top=.80)
  if name=='main_ber':
   from curve_markers import style_main
   style_main(fig)
  finish(fig,name,'Five-method comparison after adaptation. CNN est. is the CNN estimator baseline. '+ZERO,wide=stacked)
 if only is not None:return
 tr=rows(B/'source_data/paper/transition_curves.csv')
 fig,(ax,right)=plt.subplots(1,2,figsize=(3.5,3.0),gridspec_kw={'width_ratios':[1,1.5]});style(ax,low=3e-5);ax.set_xlim(3.6,12.4)
 before=rows(P/'results/before_curves_side_20261016/before_curves.csv')
 for method,col,mk in [('FastSET',COL[0],MK[0]),('CNN',COL[1],MK[1])]:
  curve(ax,[r for r in before if r['case']=='B2C' and r['method']==method],'snr',method+' before',col,mk,'--',asset='environment_transition_performance',panel='B2C before')
  ax.lines[-1].set_markerfacecolor('white')
 for case,ls in [('A2C','-'),('B2C','-.')]:
  for method,col,mk in [('FastSET',COL[0],MK[0]),('CNN',COL[1],MK[1])]:curve(ax,[r for r in tr if r['scenario']==case and r['method']==method],'snr',case+' '+method,col,mk,ls,asset='environment_transition_performance',panel=case)
 times=rows(B/'tables/transition_times.csv');cases=['A2B','A2C','B2C']
 pairs=[[float(next(r for r in times if r['scenario']==case and r['method']==method)['total_seconds']) for method in ['FastSET','CNN']] for case in cases]
 paired_times(right,cases,pairs,COL[:2]);right.set_xlabel('Transition')
 h,l=ax.get_legend_handles_labels();order=[0,2,4,1,3,5];fig.legend([h[i] for i in order],[l[i] for i in order],ncol=2,loc='upper center',bbox_to_anchor=(.55,1),frameon=False,columnspacing=.65,handlelength=1.8)
 fig.subplots_adjust(left=.15,right=.98,bottom=.19,top=.74,wspace=.52)
 finish(fig,'environment_transition_performance','Left: two B2C before curves and four A2C/B2C after curves; A2B BER is in the main comparison. Right: paired input-inclusive FastSET/CNN times in seconds, with the CNN/FastSET ratio above each pair. '+ZERO)
 sr=rows(P/'results/conference864_20261016/paper/main_fastset_cnn_curves.csv')
 fig,ax=plt.subplots(figsize=(3.5,2.15));style(ax,xmax=18)
 for method,col,mk in [('FastSET',COL[0],MK[0]),('CNN',COL[1],MK[1])]:curve(ax,[r for r in sr if r['scenario']=='Source A (pretrained)' and r['method']==method],'snr',method,col,mk,asset='sourceA_control')
 ax.legend(ncol=2,frameon=False,loc='lower center',bbox_to_anchor=(.5,1.01));fig.subplots_adjust(left=.17,right=.99,bottom=.22,top=.84)
 finish(fig,'sourceA_control','Supplement: source-A pretrained domain control, without online adaptation. '+ZERO.replace('the main display is 4–12 dB','this supplemental display is 4–18 dB'))
 rr=rows(B/'tables/main_adaptation_curve.csv')
 combined=[dict(r,scenario='A2B') for r in rr]
 sources={'FastSET':P/'results/rt/continuation_20261015/A2C_d8_w64/stages.csv','CNN':P/'results/campaign_finish_20261015/remote_reports/validation_A2C_20261015/runs/A2C_CNN_dem10/stages.csv'}
 for method,path in sources.items():
  raw=[r for r in rows(path) if r['test_seed']=='56']
  times={int(r['total_iteration']):r for r in rows(P/f'results/timing_resident_20261016/statistics/A2C_{method}/trajectory.csv')}
  for r in raw:
   i=0 if r['stage']=='pretrained' else int(r['iteration'])+(5 if r['stage']=='dem' else 0)
   combined.append(dict(r,method=method,scenario='A2C',total_iteration=i,total_seconds=float(times[i]['total_seconds']) if i else 0))
  assert len(raw)==len(times)+1
